	unsigned int	tp_retire_blk_tov; /* timeout in msecs */				// 超时时间（毫秒），超时后即使内存块没有被数据完全填满也会被内核停用（参考下文）,以便用户能尽快读取数据
	unsigned int	tp_sizeof_priv; /* offset to private data area */		// 每个内存块中私有区域的大小。用户可以使用这个区域存放与每个内存块有关的任何信息；
	unsigned int	tp_feature_req_word;									// 一组标志（目前实际上只有一个标志），可以用来启动某些附加功能。
};
```
这里把 `block_size` 设为 0x8000，用来消耗零散的 order-3 页





## 溢出点

```c
static int tpacket_rcv(struct sk_buff *skb, struct net_device *dev,
               struct packet_type *pt, struct net_device *orig_dev)
{
    ...
    h.raw = packet_current_rx_frame(po, skb, TP_STATUS_KERNEL, (macoff+snaplen)); 	// (1)计算传入的 tp_sizeof_priv, 以控制伪造写入的地址 !!!!
    ...
    skb_copy_bits(skb, 0, h.raw + macoff, snaplen);					// (2)拷贝时产生溢出 !!!!!!!!!!!!!!
    ...
}
```

 `tpacket_rcv` 是 Linux 内核中用于处理接收到的网络数据包的函数。它对 AF_PACKET 套接字上传入的数据包执行接收操作。AF_PACKET 套接字允许用户态程序直接访问链路层帧，常用于 tcpdump、Wireshark 等网络嗅探和构包工具。下面是该函数的详细工作流程和说明：

### 函数参数
- `struct sk_buff *skb`：传入的数据包缓冲区。
- `struct net_device *dev`：接收数据包的网络设备。
- `struct packet_type *pt`：数据包类型信息，用于绑定到特定协议。
- `struct net_device *orig_dev`：原始网络设备。

### 函数工作流程

1. **初步检查与变量初始化**：
   - 检查数据包类型是否为 `PACKET_LOOPBACK`，如果是则丢弃。
   - 获取套接字 `sock` 和 `packet_sock` 结构体。
   - 检查数据包是否来自同一个网络命名空间，否则丢弃。

2. **处理数据包头部**：
   - 根据设备类型和套接字类型处理数据包头部。如果设备有头部操作且套接字类型不是 `SOCK_DGRAM`，就把数据包头部推回数据包中。如果数据包类型是 `PACKET_OUTGOING`，则拉取网络层偏移。

3. **数据包过滤**：
   - 运行过滤器（`run_filter`）决定是否接受该数据包。如果过滤结果为零，则丢弃数据包。

4. **校验和处理**：
   - 根据数据包的校验和状态设置状态标志。

5. **截断数据包**：
   - 根据过滤结果截断数据包长度。

6. **计算偏移**：
   - 计算 MAC 层和网络层偏移。

7. **处理环形缓冲区**：
   - 检查并处理环形缓冲区的帧大小。如有需要且缓冲区是共享的，则克隆或获取数据包。

8. **锁定接收队列并处理接收帧**：
   - 锁定套接字的接收队列并获取当前接收帧。如果失败，则丢弃数据包并计数。
   - 递增接收头指针。

9. **处理 Virtio 网络头**：
   - 如果存在 Virtio 网络头，则从数据包中提取并填入接收缓冲区。

10. **拷贝数据**：
    - 把数据包内容拷贝到接收缓冲区。

11. **时间戳处理**：
    - 获取数据包的时间戳并设置到接收缓冲区头部。

12. **设置头部字段**：
    - 根据不同的 TPACKET 版本设置接收缓冲区头部字段。

13. **设置套接字地址**：
    - 用数据包的链路层信息填充 `sockaddr_ll` 结构体。

14. **缓存一致性处理**：
    - 如果体系结构实现了 dcache 页刷新，则刷新缓存以确保数据一致性。

15. **设置状态并通知**：
    - 设置接收缓冲区状态，并调用 `sk_data_ready` 通知用户态有新数据到达。

### 错误处理与数据包释放
- 如果处理过程中出错，会跳转到 `drop_n_restore` 或 `drop_n_account` 标签进行错误处理和数据包释放。

`tpacket_rcv` 函数主要负责接收和处理网络数据包，把数据拷贝到用户态可访问的缓冲区中，并根据不同的 TPACKET 版本设置相应的头部信息。该函数涉及数据包过滤、校验和处理、时间戳处理和缓存一致性处理等操作，以确保数据包能被正确地交付给用户态。

内核调用 tpacket_rcv() 函数接收数据包；每当内核收到一个新数据包，都应当把它保存到环形缓冲区中。关键函数是 __packet_lookup_frame_in_block()，它计算当前环形缓冲区中可接收数据的起始地址。该函数的主要工作是：

1.  检查当前活跃的内存块是否有足够空间存放该数据包；

2.  如果空间足够，就把数据包保存到当前内存块中并返回；

3. 如果空间不够，就调度下一个内存块，并把数据包保存到下一个内存块中。

大致流程如下

```c
static int tpacket_rcv(struct sk_buff *skb, struct net_device *dev,
               struct packet_type *pt, struct net_device *orig_dev)
{
    ...
    h.raw = packet_current_rx_frame(po, skb, TP_STATUS_KERNEL, (macoff+snaplen)); 	// (1)计算传入的 tp_sizeof_priv, 以控制伪造写入的地址 !!!!
    ...
    skb_copy_bits(skb, 0, h.raw + macoff, snaplen);					// (2)拷贝时产生溢出 !!!!!!!!!!!!!!
    ...
}
static void *packet_current_rx_frame(struct packet_sock *po,						// (1-2)
                        struct sk_buff *skb,
                        int status, unsigned int len)
{
    char *curr = NULL;
    switch (po->tp_version) {
    ...
    case TPACKET_V3:
        return __packet_lookup_frame_in_block(po, skb, status, len);
    ...
    }
}
// __packet_lookup_frame_in_block —— 返回当前缓冲区中可接收数据的起始地址					// (1-3)
static void *__packet_lookup_frame_in_block(struct packet_sock *po,
                        struct sk_buff *skb,
                        int status,
                        unsigned int len
                        )
{
    struct tpacket_kbdq_core *pkc;
    struct tpacket_block_desc *pbd;
    char *curr, *end;
    pkc = GET_PBDQC_FROM_RB(&po->rx_ring);
    pbd = GET_CURR_PBLOCK_DESC_FROM_CORE(pkc);
    ...
    curr = pkc->nxt_offset;
    pkc->skb = skb;
    end = (char *)pbd + pkc->kblk_size;
    /* first try the current block */
    if (curr+TOTAL_PKT_LEN_INCL_ALIGN(len) nxt_offset;
}
```

### 整体流程
1. **调用 `tpacket_rcv` 函数接收数据包**
2. **计算当前接收帧的地址**
3. **检查并分配缓冲区**
4. **把数据拷贝到缓冲区**
5. **处理缓冲区填充与状态**

### 详细步骤

#### 1. `tpacket_rcv` 函数
该函数是数据包接收的入口。它处理数据包的各种属性，并把数据包拷贝到合适的缓冲区中。

```c
h.raw = packet_current_rx_frame(po, skb, TP_STATUS_KERNEL, (macoff + snaplen));
```
- 这一行计算传入帧的地址，调用 `packet_current_rx_frame` 获取当前接收帧的地址。

```c
skb_copy_bits(skb, 0, h.raw + macoff, snaplen);
```
- 这一行把数据包内容拷贝到计算出的缓冲区地址。如果计算出的地址或长度不正确，就可能存在溢出风险。

#### 2. `packet_current_rx_frame` 函数
该函数根据 TPACKET 版本选择相应的函数来查找当前接收帧的地址。

```c
switch (po->tp_version) {
    ...
    case TPACKET_V3:
        return __packet_lookup_frame_in_block(po, skb, status, len);
    ...
}
```
- 对于 TPACKET_V3 版本，会调用 `__packet_lookup_frame_in_block` 函数。

#### 3. `__packet_lookup_frame_in_block` 函数
该函数在当前块中查找可用的接收帧，必要时分配新的块。

```c
pkc = GET_PBDQC_FROM_RB(&po->rx_ring);
pbd = GET_CURR_PBLOCK_DESC_FROM_CORE(pkc);
curr = pkc->nxt_offset;
end = (char *)pbd + pkc->kblk_size;
```
- `pkc` 是核心缓冲区描述符，`pbd` 是当前块描述符，`curr` 是当前偏移，`end` 是当前块的结束地址。

```c
if (curr + TOTAL_PKT_LEN_INCL_ALIGN(len) nxt_offset;
}

static void prb_open_block(struct tpacket_kbdq_core *pkc1,
	struct tpacket_block_desc *pbd1)
{
 pkc1->pkblk_start = (char *)pbd1;
	pkc1->nxt_offset = pkc1->pkblk_start + BLK_PLUS_PRIV(pkc1->blk_sizeof_priv);
}
```
- 打开新块并返回新块的起始可用位置。此时如果 `blk_sizeof_priv` 非常大，`nxt_offset` 就会越界


然后数据被拷贝到 `pkc1->nxt_offset`，此时就发生了越界写

```c
static int tpacket_rcv(struct sk_buff *skb, struct net_device *dev,
               struct packet_type *pt, struct net_device *orig_dev)
{
    ...
